import { computed, effect, Injectable, signal } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class TareasStore {
  private readonly _tareas = signal<Tarea[]>(JSON.parse(localStorage.getItem('tareas') ?? '[]'));

  readonly tareas = this._tareas.asReadonly();
  readonly pendientes = computed(() => this._tareas().filter(t => !t.hecha).length);

  constructor() {
    effect(() => localStorage.setItem('tareas', JSON.stringify(this._tareas())));
  }

  agregar(titulo: string) {
    this._tareas.update(l => [...l, { id: crypto.randomUUID(), titulo, hecha: false }]);
  }

  completar(id: string) {
    this._tareas.update(l => l.map(t => (t.id === id ? { ...t, hecha: true } : t)));
  }
}
